const views={"editorial":View6};
export interface ArtemisNotFoundPagesProps{className?:string;variant?:"editorial";}
export function ArtemisNotFoundPages({className,variant="editorial"}:ArtemisNotFoundPagesProps){const View=views[variant];return <ArtemisScope className={["art:min-h-dvh art:[&>section]:min-h-dvh",className].filter(Boolean).join(" ")}><View/></ArtemisScope>;}

"use client";
// @zeus-internal
import { useEffect, useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { ARTEMIS_SPRING_PANEL, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
export default function NotFoundPagesEditorial() {
    const reduce = useReducedMotion();
    const [copyShown, setCopyShown] = useState(false);
    const [digitsShown, setDigitsShown] = useState(false);
    const [captionShown, setCaptionShown] = useState(false);
    useEffect(() => {
        const copy = setTimeout(() => setCopyShown(true), 70);
        const digits = setTimeout(() => setDigitsShown(true), 180);
        const caption = setTimeout(() => setCaptionShown(true), 340);
        return () => { clearTimeout(copy); clearTimeout(digits); clearTimeout(caption); };
    }, []);
    const press = { whileHover: reduce ? undefined : { scale: 1.01 }, whileTap: reduce ? undefined : { scale: 0.99 }, transition: ARTEMIS_SPRING_PRESS };
    return (<>
      <section className="art:flex art:min-h-[680px] art:w-full art:flex-col art:overflow-hidden art:bg-background art:text-foreground">
        <header className="art:flex art:min-h-20 art:items-center art:justify-between art:border-border/60 art:border-b art:px-5 art:@min-[640px]/artemis:px-8">
          <a href="/" className="art:font-sans art:text-xl art:tracking-[-0.03em] art:focus-visible:outline-2 art:focus-visible:outline-ring">
            {"Research team"}
          </a>
          <span className="art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.2em]">
            {"Vol. 404 \u00B7 Missing"}
          </span>
        </header>
        <div className="art:grid art:flex-1 art:grid-rows-[auto_1fr] art:@min-[1024px]/artemis:grid-cols-[0.38fr_0.62fr] art:@min-[1024px]/artemis:grid-rows-1">
          <motion.div initial={{ opacity: 0, x: -16 }} animate={{ opacity: copyShown || reduce ? 1 : 0, x: copyShown || reduce ? 0 : -16 }} transition={reduce ? { duration: 0 } : ARTEMIS_SPRING_PANEL} className="art:flex art:flex-col art:justify-between art:border-border/60 art:border-b art:p-6 art:@min-[640px]/artemis:p-10 art:@min-[1024px]/artemis:border-r art:@min-[1024px]/artemis:border-b-0 art:@min-[1024px]/artemis:p-12">
            <div>
              <p className="art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.2em]">
                {"Page 404"}
              </p>
              <h1 className="art:mt-6 art:max-w-sm art:text-balance art:font-sans art:leading-tight art:tracking-[-0.04em] art:text-4xl art:@min-[768px]/artemis:text-5xl art:font-medium">
                {"The page you wanted was edited out."}
              </h1>
            </div>
            <div className="art:mt-10 art:flex art:flex-wrap art:gap-3">
              <motion.a {...press} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:h-12 art:gap-2 art:px-6 art:text-base art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:rounded-full" href="/" tabIndex={0}>
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-corner-up-left art:size-4" aria-hidden="true">
                  <path d="M20 20v-7a4 4 0 0 0-4-4H4"/>
                  <path d="M9 14 4 9l5-5"/>
                </svg>
                {"Return home"}
              </motion.a>
              <motion.a {...press} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:h-12 art:gap-2 art:px-6 art:text-base art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:rounded-full" href="/archive" tabIndex={0}>
                {"Browse archive"}
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-4" aria-hidden="true">
                  <path d="M7 7h10v10"/>
                  <path d="M7 17 17 7"/>
                </svg>
              </motion.a>
            </div>
          </motion.div>
          <div className="art:relative art:flex art:min-h-[380px] art:items-end art:overflow-hidden art:bg-primary art:px-3 art:pt-10 art:text-primary-foreground art:[container-type:inline-size] art:@min-[640px]/artemis:min-h-[470px] art:@min-[640px]/artemis:px-6 art:@min-[1024px]/artemis:min-h-0">
            <div aria-hidden="true" className="art:absolute art:inset-0 art:opacity-30 art:[background-image:linear-gradient(to_right,color-mix(in_oklch,var(--artemis-primary-foreground)_22%,transparent)_1px,transparent_1px)] art:[background-size:25%_100%]"/>
            <div className="art:relative art:flex art:w-full art:items-end art:justify-between art:overflow-hidden">
              <motion.span initial={{ opacity: 0, y: "26%" }} animate={{ opacity: digitsShown || reduce ? 1 : 0, y: digitsShown || reduce ? "0%" : "26%" }} transition={reduce ? { duration: 0 } : { ...ARTEMIS_SPRING_PANEL, delay: 0 * 0.06 }} className="art:font-sans art:text-9xl art:leading-tight art:tracking-[-0.12em]">
                {"4"}
              </motion.span>
              <motion.span initial={{ opacity: 0, y: "26%" }} animate={{ opacity: digitsShown || reduce ? 1 : 0, y: digitsShown || reduce ? "0%" : "26%" }} transition={reduce ? { duration: 0 } : { ...ARTEMIS_SPRING_PANEL, delay: 1 * 0.06 }} className="art:font-sans art:text-9xl art:leading-tight art:tracking-[-0.12em]">
                {"0"}
              </motion.span>
              <motion.span initial={{ opacity: 0, y: "26%" }} animate={{ opacity: digitsShown || reduce ? 1 : 0, y: digitsShown || reduce ? "0%" : "26%" }} transition={reduce ? { duration: 0 } : { ...ARTEMIS_SPRING_PANEL, delay: 2 * 0.06 }} className="art:font-sans art:text-9xl art:leading-tight art:tracking-[-0.12em]">
                {"4"}
              </motion.span>
            </div>
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: captionShown || reduce ? 1 : 0 }} transition={{ duration: reduce ? 0 : 0.3, ease: "easeOut" }} className="art:absolute art:right-5 art:top-5 art:max-w-36 art:text-right art:font-mono art:text-xs art:text-primary-foreground/60 art:uppercase art:leading-5 art:tracking-[0.16em] art:@min-[640px]/artemis:right-8 art:@min-[640px]/artemis:top-8">
              {"Missing page"}
            </motion.div>
          </div>
        </div>
      </section>
    </>);
}
